package com.offlinepass.app.vault

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner

/**
 * Device-wrap protocol tests (Plan 2 rev 2). The vectors are generated by
 * scripts/gen_device_wrap_vectors.py and are the SAME numbers the extension's
 * selftest page asserts — any mismatch means the two implementations
 * disagree on the wire format. Rev 2: wrap-once/target-many (a CEK encrypts
 * the payload; each paired key gets its own wrapped-CEK blob).
 */
@RunWith(RobolectricTestRunner::class)
class DeviceWrapTest {

    // Auto-generated: python3 scripts/gen_device_wrap_vectors.py
    private val vecDevicePub = hex(
        "0420eb2418a4d73b6e941055d4e4c27d3cefe2363114dbc0520489f9bfc314d27d6fd4da9b14eb530e95449d24b9124f98dc2ca4feb3b2a5d8ac1c2549e567a1c8")
    private val vecKey1 = "72dbb7336c767800"   // hex(SHA-256(credId1))[0..8]  (R1)
    private val vecDevice2Pub = hex(
        "0452c68d25e9f4f21a9c9317c14399629e1f43fbf08ff77c281312c026b4dbda5a173c2784b9e80923069f3a6246e37bd5610f87a5f68d49234d4da0e342dccc4c")
    private val vecKey2 = "ca2a4fe727faaecf"
    private val vecCek = hex(
        "606162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f")
    private val vecPayloadCt = ""
    private val vecEph1Scalar = hex(
        "8341425cafede9d24b0599aefdfdeff1c1526ed75b07217eb99bf8c0b7498b81")
    private val vecEph1Pub = hex(
        "049a781ca6d055a7f30d0c9ff87936c739f6816ef5f5e72b4b946404b0a1a83b2ac19f842945ea2bf65aa1649b2b02ff79854c8d5ecfcd403862e8a97ea66c71c1")
    private val vecT1Iv = hex("000102030405060708090a0b")
    private val vecT1Ct = "sXfCVNY7rbqdxEnqunN4eaD0OihCLT8j8Jfg3LAE5zAvkfzbMM25St9DiJqNwMn3"
    private val vecEph2Scalar = hex(
        "c2f18a8f50fe4dacf1dc18a4a889bdd6c28a8baf6c3d25dd8d4c47336e92dbab")
    private val vecEph2Pub = hex(
        "043f95c5f6edf6fe05c7e269ef428ea61614bf456f0168ddb464170e6b7687491a9c4f9a70a224533b307bc7cf7766688fd23eac5079e9aa88f5244b03d1449510")
    private val vecT2Iv = hex("101112131415161718191a1b")
    private val vecT2Ct = "wE8HlyTS7wSSIrNijKCBP3d0+aspPxEyNOgneGJoVDCVRJ/IjHNiX7hWYk7IFZDf"
    private val vecPayload = """{"itemId":"vec-item-0000","shareId":"local","data":{"type":"login","metadata":{"name":"Vector Test","itemUuid":"vec-item-0000"},"content":{"itemEmail":"","itemUsername":"vector","password":"s3cret-vector","urls":["https://example.test"],"totpUri":"","passkeys":[]}},"state":1}"""

    private fun hex(s: String): ByteArray =
        ByteArray(s.length / 2) { i -> s.substring(i * 2, i * 2 + 2).toInt(16).toByte() }

    @Test
    fun wrapMatchesCrossImplVector_singleTarget() {
        val out = DeviceWrap.wrapDeterministic(vecPayload, vecCek, listOf(
            DeviceWrap.TestTarget(vecDevicePub, vecKey1, vecEph1Scalar, vecEph1Pub, vecT1Iv)))
        val obj = org.json.JSONObject(out)
        assertEquals(1, obj.getInt("v"))
        assertEquals("offlinepass-wrap", obj.getString("type"))
        val payload = obj.getJSONObject("payload")
        assertEquals("AQIDBAUGBwgJCgsM", payload.getString("iv"))
        assertEquals(vecPayloadCt, payload.getString("ct"))
        val targets = obj.getJSONArray("targets")
        assertEquals(1, targets.length())
        val t = targets.getJSONObject(0)
        assertEquals(vecKey1, t.getString("keyId"))
        assertEquals(vecEph1Pub.encodeB64(), t.getString("epk"))
        assertEquals(vecT1Iv.encodeB64(), t.getString("iv"))
        assertEquals(vecT1Ct, t.getString("ct"))
    }

    @Test
    fun wrapMatchesCrossImplVector_twoTargets() {
        val out = DeviceWrap.wrapDeterministic(vecPayload, vecCek, listOf(
            DeviceWrap.TestTarget(vecDevicePub, vecKey1, vecEph1Scalar, vecEph1Pub, vecT1Iv),
            DeviceWrap.TestTarget(vecDevice2Pub, vecKey2, vecEph2Scalar, vecEph2Pub, vecT2Iv)))
        val targets = org.json.JSONObject(out).getJSONArray("targets")
        assertEquals(2, targets.length())
        // The payload layer is identical across targets — decrypting with
        // either key must yield the same CEK and thus the same plaintext.
        assertEquals(vecT1Ct, targets.getJSONObject(0).getString("ct"))
        assertEquals(vecT2Ct, targets.getJSONObject(1).getString("ct"))
        assertEquals(vecKey2, targets.getJSONObject(1).getString("keyId"))
    }

    @Test
    fun wrapIsRandomized() {
        val record = sampleRecord()
        val a = DeviceWrap.wrap(vecPayload, listOf(record))
        val b = DeviceWrap.wrap(vecPayload, listOf(record))
        assertTrue(a != b) // fresh CEK + ephemeral keys + IVs per paste
    }

    @Test
    fun hkdfRfc5869TestCase1() {
        val ikm = ByteArray(22) { 0x0b }
        val salt = hex("000102030405060708090a0b0c")
        val info = hex("f0f1f2f3f4f5f6f7f8f9")
        val okm = Hkdf.derive(ikm, salt, info, 42)
        assertEquals("3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865",
            okm.joinToString("") { "%02x".format(it) })
    }

    private fun sampleRecord() = DeviceRecord(
        id = vecKey1, name = "vector-key",
        credId = "ICEiIyQlJicoKSorLC0uLzAxMjM0NTY3ODk6Ozw9Pj8=",
        pub = vecDevicePub.encodeB64(), keyId = vecKey1, added = 1762500000,
        salt = "q5oYXr3CRo9//Fj24tuSuUAAIqOrkORNlkzE7krAbYg=",
        wrappedIv = "AAECAwQFBgcICQoL", wrappedCt = "(not needed for wrap)")

    private fun ByteArray.encodeB64(): String =
        java.util.Base64.getEncoder().encodeToString(this)
}

@RunWith(RobolectricTestRunner::class)
class DeviceRecordTest {

    @Test
    fun parsesPairingPayload() {
        val payload = """{"type":"offlinepass-device","device":{"id":"72dbb7336c767800",
            "name":"ko-yk5","credId":"ICEiIyQlJicoKSorLC0uLzAxMjM0NTY3ODk6Ozw9Pj8=",
            "pub":"BCDrJBik1ztulBBV1OTCfTzv4jYxFNvAUgSJ+b/DFNJ9b9TamxTrUw6VRJ0kuRJPmNwspP6zsqXYrBwlSeVnocg=",
            "keyId":"72dbb7336c767800","added":1762500000,
            "salt":"q5oYXr3CRo9//Fj24tuSuUAAIqOrkORNlkzE7krAbYg=",
            "wrapped":{"iv":"AAECAwQFBgcICQoL","ct":"AAAA"}}}""".replace("\n", "")
        val r = DeviceRecord.fromPayload(payload)
        assertNotNull(r)
        assertEquals("ko-yk5", r!!.name)
        assertEquals("72dbb7336c767800", r.keyId)
        assertEquals(r.keyId, r.id)
    }

    @Test
    fun rejectsNonPairingPayloads() {
        assertNull(DeviceRecord.fromPayload("""[{"itemId":"x","data":{"content":{}}}]"""))
        assertNull(DeviceRecord.fromPayload("""{"v":1,"type":"offlinepass-wrap"}"""))
        assertNull(DeviceRecord.fromPayload("not json"))
        assertNull(DeviceRecord.fromPayload("""{"type":"offlinepass-device"}"""))
    }

    @Test
    fun envelopeRoundTripsDevices() {
        val env = Envelope.fromJson("""{"vaults":{"local":{"items":[]}}}""")
        env.devices.add(DeviceRecord(
            id = "k1", name = "chromebook", credId = "cred", pub = "pub",
            keyId = "k1", added = 1, salt = "salt", wrappedIv = "iv", wrappedCt = "ct"))
        val again = Envelope.fromJson(env.toJsonObject().toString())
        assertEquals(1, again.devices.size)
        assertEquals("chromebook", again.devices[0].name)
        assertEquals("ct", again.devices[0].wrappedCt)
    }

    @Test
    fun mergeUnionsDevicesNewerWinsAndHonorsRemovals() {
        val d1 = DeviceRecord("k1", "a", "c1", "p1", "k1", 1, "s", "iv", "ct")
        val d2 = DeviceRecord("k2", "b", "c2", "p2", "k2", 2, "s", "iv", "ct")
        val mine = Envelope.fromJson("""{"vaults":{"local":{"items":[]}}}""")
        mine.devices.add(d1)
        val theirs = Envelope.fromJson("""{"vaults":{"local":{"items":[]}}}""")
        theirs.devices.add(d2)

        val merged = VaultMerge.unionMerge(mine, theirs)
        assertEquals(setOf("k1", "k2"), merged.devices.map { it.keyId }.toSet())

        // Removal on one side wins after sync.
        theirs.stageRemoveForTest("k2")
        val merged2 = VaultMerge.unionMerge(mine, theirs)
        assertEquals(listOf("k1"), merged2.devices.map { it.keyId })
        assertTrue("k2" in merged2.removedDeviceIds)

        // R3: same keyId on both sides with different content — the NEWER
        // envelope's copy wins (record updates must propagate through sync).
        val olderUpdated = Envelope.fromJson("""{"rev":5,"vaults":{"local":{"items":[]}}}""")
        olderUpdated.devices.add(DeviceRecord("k1", "stale-name", "c1", "p1", "k1", 1, "s", "iv", "old"))
        val newerUpdated = Envelope.fromJson("""{"rev":9,"vaults":{"local":{"items":[]}}}""")
        newerUpdated.devices.add(DeviceRecord("k1", "fresh-name", "c1", "p1", "k1", 9, "s", "iv", "new"))
        val merged3 = VaultMerge.unionMerge(olderUpdated, newerUpdated)
        assertEquals(1, merged3.devices.size)
        assertEquals("fresh-name", merged3.devices[0].name)
        assertEquals("new", merged3.devices[0].wrappedCt)
    }
}

/** Test hook: DeviceRecord removal without going through VaultSession. */
private fun Envelope.stageRemoveForTest(keyId: String) {
    devices.removeAll { it.keyId == keyId }
    removedDeviceIds.add(keyId)
}
